// The offline data set: firearm models, ammo boxes and calibers from the GunsNPrices catalog.
// src/data/catalog.json is generated by scripts/build-data.mjs; see the README for where the numbers come from.
import raw from '../data/catalog.json';

export type GunType = 'handgun' | 'rifle' | 'shotgun';
export type CaliberType = 'handgun' | 'rifle' | 'rimfire' | 'shotgun';

export interface GunRow {
  kind: 'gun';
  brand: string;
  family: string;
  model: string;
  type: GunType;
  /** standard caliber name, e.g. "9×19mm Parabellum" */
  caliber: string;
  /** product title, e.g. 'Glock 19 Gen 5 9mm 4.02" 15rd Pistol' */
  title: string;
  /** typical magazine capacity */
  capacity: number;
  /** typical barrel length, inches */
  barrel: number;
  /** lowest in-stock price, USD */
  priceMin: number | null;
  /** median in-stock price, USD */
  priceMedian: number;
  /** store listings of this model */
  listings: number;
}

export interface AmmoRow {
  kind: 'ammo';
  /** store title, e.g. "Sig Sauer 9mm 115gr FMJ Elite Ball Ammunition 50rds" */
  title: string;
  brand: string;
  caliber: string;
  caliberType: CaliberType;
  rounds: number;
  /** in-stock box price, USD */
  price: number;
}

export type Row = GunRow | AmmoRow;

export interface CaliberInfo {
  name: string;
  type: CaliberType;
  /** gun and ammo listings in this caliber */
  products: number;
}

interface Table {
  fields: string[];
  rows: (string | number | null)[][];
}
interface RawCatalog {
  version: number;
  snapshot: string;
  attribution: string;
  guns: Table;
  ammo: Table;
  calibers: Table;
  caliberWords: string[];
}

const data = raw as unknown as RawCatalog;

function objects<T>(table: Table, extra: Partial<T>): T[] {
  return table.rows.map((r) => {
    const o: Record<string, unknown> = { ...extra };
    table.fields.forEach((f, i) => (o[f] = r[i]));
    return o as T;
  });
}

export const SNAPSHOT: string = data.snapshot;
export const ATTRIBUTION: string = data.attribution;
/** firearm models, most listed first */
export const GUNS: readonly GunRow[] = objects<GunRow>(data.guns, { kind: 'gun' });
/** ammo boxes, grouped by caliber, most listed caliber first */
export const AMMO: readonly AmmoRow[] = objects<AmmoRow>(data.ammo, { kind: 'ammo' });
/** calibers, most listed first */
export const CALIBERS: readonly CaliberInfo[] = objects<CaliberInfo>(data.calibers, {});
export const CALIBER_WORDS: ReadonlySet<string> = new Set(data.caliberWords);
